"""Thread-safe client registry for WebSocket connections."""

import uuid
import threading
from typing import Dict, Optional, Any


class ClientRegistry:
    """Manages connected WebSocket clients with thread-safe operations."""

    def __init__(self):
        self._clients: Dict[str, Any] = {}
        self._lock = threading.RLock()

    def register(self, websocket: Any) -> str:
        """Register a new client and return its unique ID."""
        client_id = str(uuid.uuid4())
        with self._lock:
            self._clients[client_id] = websocket
        return client_id

    def unregister(self, client_id: str) -> None:
        """Unregister a client by ID."""
        with self._lock:
            self._clients.pop(client_id, None)

    def get_client(self, client_id: str) -> Optional[Any]:
        """Get a specific client by ID."""
        with self._lock:
            return self._clients.get(client_id)

    def get_all_clients(self) -> Dict[str, Any]:
        """Get a snapshot of all connected clients."""
        with self._lock:
            return dict(self._clients)

    def get_client_count(self) -> int:
        """Get count of connected clients."""
        with self._lock:
            return len(self._clients)

"""Message validation and handling for the notification server."""

import json
from datetime import datetime
from typing import Dict, Any, Optional


class Message:
    """Represents a notification message."""

    SUPPORTED_TYPES = {'broadcast', 'direct', 'system'}

    def __init__(self, message_type: str, payload: Dict[str, Any], timestamp: Optional[str] = None):
        self.type = message_type
        self.payload = payload
        self.timestamp = timestamp or datetime.utcnow().isoformat()

    def to_json(self) -> str:
        """Serialize message to JSON string."""
        return json.dumps({
            'type': self.type,
            'payload': self.payload,
            'timestamp': self.timestamp
        })

    @staticmethod
    def from_json(data: str) -> 'Message':
        """Deserialize message from JSON string."""
        obj = json.loads(data)
        return Message(
            message_type=obj.get('type'),
            payload=obj.get('payload', {}),
            timestamp=obj.get('timestamp')
        )


class MessageHandler:
    """Validates and handles notification messages."""

    SUPPORTED_TYPES = {'broadcast', 'direct', 'system'}

    @staticmethod
    def validate_message(data: str) -> bool:
        """Validate message format and structure."""
        try:
            obj = json.loads(data)
            return (
                'type' in obj
                and obj['type'] in MessageHandler.SUPPORTED_TYPES
                and 'payload' in obj
                and isinstance(obj['payload'], dict)
            )
        except (json.JSONDecodeError, TypeError, ValueError):
            return False

